.gold-cta-btn .arrow { transition: 0.3s; }
.gold-cta-btn:hover .arrow { transform: translateX(5px); }

@media(max-width: 768px) {
    .post-hero { height: 380px; }
    .post-hero h1 { font-size: 32px; }
